   138  static char *
   139  strsep_char(char *strp, const char *end, char delim)
   140  {
   141      char *ptr;
   142
   143      if (UNLIKELY(!strp))
   144          return NULL;
   145
   146      if (UNLIKELY(strp > end))
   147          return NULL;
   148
   149      ptr = strchr(strp, delim);
   150      if (UNLIKELY(!ptr))
   151          return NULL;
   152
   153      *ptr = '\0';
   154      return ptr + 1;
   155  }
