   157  static char *
   158  parse_proxy_protocol_v1(struct lwan_request *request, char *buffer)
   159  {
   160      static const size_t line_size = 108;
   161      char *end, *protocol, *src_addr, *dst_addr, *src_port, *dst_port;
   162      unsigned int size;
   163      struct lwan_proxy *const proxy = request->proxy;
   164
   165      end = memchr(buffer, '\r', line_size);
   166      if (UNLIKELY(!end || end[1] != '\n'))
   167          return NULL;
   168      *end = '\0';
   169      size = (unsigned int) (end + 2 - buffer);
   170
   171      protocol = buffer + sizeof("PROXY ") - 1;
   172      src_addr = strsep_char(protocol, end, ' ');
   173      dst_addr = strsep_char(src_addr, end, ' ');
   174      src_port = strsep_char(dst_addr, end, ' ');
   175      dst_port = strsep_char(src_port, end, ' ');
   176
   177      if (UNLIKELY(!dst_port))
   178          return NULL;
   179
   180      STRING_SWITCH(protocol) {
   181      case STR4_INT('T', 'C', 'P', '4'): {
   182          struct sockaddr_in *from = &proxy->from.ipv4;
   183          struct sockaddr_in *to = &proxy->to.ipv4;
   184
   185          from->sin_family = to->sin_family = AF_INET;
   186
   187          if (UNLIKELY(inet_pton(AF_INET, src_addr, &from->sin_addr) <= 0))
   188              return NULL;
   189          if (UNLIKELY(inet_pton(AF_INET, dst_addr, &to->sin_addr) <= 0))
   190              return NULL;
   191          if (UNLIKELY(!parse_ascii_port(src_port, &from->sin_port)))
   192              return NULL;
   193          if (UNLIKELY(!parse_ascii_port(dst_port, &to->sin_port)))
   194              return NULL;
   195
   196          break;
   197      }
   198      case STR4_INT('T', 'C', 'P', '6'): {
   199          struct sockaddr_in6 *from = &proxy->from.ipv6;
   200          struct sockaddr_in6 *to = &proxy->to.ipv6;
   201
   202          from->sin6_family = to->sin6_family = AF_INET6;
   203
   204          if (UNLIKELY(inet_pton(AF_INET6, src_addr, &from->sin6_addr) <= 0))
   205              return NULL;
   206          if (UNLIKELY(inet_pton(AF_INET6, dst_addr, &to->sin6_addr) <= 0))
   207              return NULL;
   208          if (UNLIKELY(!parse_ascii_port(src_port, &from->sin6_port)))
   209              return NULL;
   210          if (UNLIKELY(!parse_ascii_port(dst_port, &to->sin6_port)))
   211              return NULL;
   212
   213          break;
   214      }
   215      default:
   216          return NULL;
   217      }
   218
   219      request->flags |= REQUEST_PROXIED;
   220      return buffer + size;
   221  }
