    92                  continue;
    93              }
    94
    95              goto error;
    96          }
    97          default:
    98              config_error(f, "Expected username = password");
    99              break;
   100          }
   101      }
   102
   103      if (config_last_error(f)) {
   104          lwan_status_error("Error on password file \"%s\", line %d: %s",
   105                key, config_cur_line(f), config_last_error(f));
   106          goto error;
   107      }
   108
   109      config_close(f);
   110      return (struct cache_entry *)rpf;
