   447  static void parse_fragment_and_query(struct lwan_request *request,
   448                                       const char *space)
   449  {
   450      struct lwan_request_parser_helper *helper = request->helper;
   451
   452      /* Fragments shouldn't be received by the server, but look for them anyway
   453       * just in case. */
   454      char *fragment = memrchr(request->url.value, '#', request->url.len);
   455      if (UNLIKELY(fragment != NULL)) {
   456          *fragment = '\0';
   457          request->url.len = (size_t)(fragment - request->url.value);
   458          space = fragment;
   459      }
   460
   461      char *query_string = memchr(request->url.value, '?', request->url.len);
   462      if (query_string) {
   463          *query_string = '\0';
   464          helper->query_string.value = query_string + 1;
   465          helper->query_string.len = (size_t)(space - query_string - 1);
   466          request->url.len -= helper->query_string.len + 1;
   467      }
