   470  static char *
   471  identify_http_path(struct lwan_request *request, char *buffer)
   472  {
   473      struct lwan_request_parser_helper *helper = request->helper;
   474      static const size_t minimal_request_line_len = sizeof("/ HTTP/1.0") - 1;
   475      char *space, *end_of_line;
   476      ptrdiff_t end_len;
   477
   478      if (UNLIKELY(*buffer != '/'))
   479          return NULL;
   480
   481      end_len = buffer - helper->buffer->value;
   482      if (UNLIKELY((size_t)end_len >= helper->buffer->len))
   483          return NULL;
   484
   485      end_of_line = memchr(buffer, '\r', helper->buffer->len - (size_t)end_len);
   486      if (UNLIKELY(!end_of_line))
   487          return NULL;
   488      if (UNLIKELY((size_t)(end_of_line - buffer) < minimal_request_line_len))
   489          return NULL;
   490      *end_of_line = '\0';
   491
   492      space = end_of_line - sizeof("HTTP/X.X");
   493
   494      request->url.value = buffer;
   495      request->url.len = (size_t)(space - buffer);
   496      parse_fragment_and_query(request, space);
   497      request->original_url = request->url;
   498
   499      *space++ = '\0';
   500
   501      STRING_SWITCH_LARGE(space) {
   502      case STR8_INT('H','T','T','P','/','1','.','0'):
   503          request->flags |= REQUEST_IS_HTTP_1_0;
   504          break;
   505      case STR8_INT('H','T','T','P','/','1','.','1'):
   506          break;
   507      default:
   508          return NULL;
   509      }
   510
   511      return end_of_line + 1;
   512  }
