   666              goto invalid_range;
   667
   668          helper->range.from = 0;
   669          helper->range.to = (off_t)to;
   670      } else if (sscanf(range, "%"SCNu64"-", &from) == 1) {
   671          if (UNLIKELY(from > OFF_MAX))
   672              goto invalid_range;
   673
   674          helper->range.from = (off_t)from;
   675          helper->range.to = -1;
   676      } else {
   677  invalid_range:
   678          helper->range.from = -1;
   679          helper->range.to = -1;
   680      }
   681  }
