   683  static void
   684  parse_accept_encoding(struct lwan_request *request)
   685  {
   686      struct lwan_request_parser_helper *helper = request->helper;
   687
   688      if (!helper->accept_encoding.len)
   689          return;
   690
   691      for (const char *p = helper->accept_encoding.value; *p; p++) {
   692          STRING_SWITCH(p) {
   693          case STR4_INT('d','e','f','l'):
   694          case STR4_INT(' ','d','e','f'):
   695              request->flags |= REQUEST_ACCEPT_DEFLATE;
   696              break;
   697          case STR4_INT('g','z','i','p'):
   698          case STR4_INT(' ','g','z','i'):
   699              request->flags |= REQUEST_ACCEPT_GZIP;
   700              break;
   701  #if defined(HAVE_BROTLI)
   702          default:
   703              while (lwan_char_isspace(*p))
   704                  p++;
   705
   706              STRING_SWITCH_SMALL(p) {
   707              case STR2_INT('b', 'r'):
   708                  request->flags |= REQUEST_ACCEPT_BROTLI;
   709                  break;
   710              }
   711  #endif
   712          }
   713
   714          if (!(p = strchr(p, ',')))
   715              break;
   716      }
   717  }
