   767  static void save_to_corpus_for_fuzzing(const struct lwan_value *orig_buffer)
   768  {
   769      struct lwan_value buffer = *orig_buffer;
   770      char corpus_name[PATH_MAX];
   771      const char *crlfcrlf;
   772      int fd;
   773
   774      if (!(crlfcrlf = memmem(buffer.value, buffer.len, "\r\n\r\n", 4)))
   775          return;
   776      buffer.len = (size_t)(crlfcrlf - buffer.value + 4);
   777
   778  try_another_file_name:
   779      snprintf(corpus_name, sizeof(corpus_name), "corpus-request-%d", rand());
   780
   781      fd = open(corpus_name, O_WRONLY | O_CLOEXEC | O_CREAT | O_EXCL, 0644);
   782      if (fd < 0)
   783          goto try_another_file_name;
   784
   785      for (ssize_t total_written = 0; total_written != (ssize_t)buffer.len;) {
   786          ssize_t r = write(fd, buffer.value, buffer.len);
   787
   788          if (r < 0) {
   789              if (errno == EAGAIN || errno == EINTR)
   790                  continue;
   791
   792              close(fd);
   793              unlink(corpus_name);
   794              goto try_another_file_name;
   795          }
   796
   797          total_written += r;
   798      }
   799
   800      close(fd);
   801      lwan_status_debug("Request saved to %s", corpus_name);
