   805  static enum lwan_http_status
   806  read_from_request_socket(struct lwan_request *request,
   807                           struct lwan_value *buffer,
   808                           const size_t buffer_size,
   809                           enum lwan_read_finalizer (*finalizer)(
   810                               size_t total_read,
   811                               size_t buffer_size,
   812                               struct lwan_request *request,
   813                               int n_packets))
   814  {
   815      struct lwan_request_parser_helper *helper = request->helper;
   816      ssize_t n;
   817      size_t total_read = 0;
   818      int n_packets = 0;
   819
   820      if (helper->next_request) {
   821          const size_t next_request_len = (size_t)(helper->next_request - buffer->value);
   822          size_t new_len;
   823
   824          if (__builtin_sub_overflow(buffer->len, next_request_len, &new_len)) {
   825              helper->next_request = NULL;
   826          } else {
   827              /* FIXME: This memmove() could be eventually removed if a better
   828               * stucture (maybe a ringbuffer, reading with readv(), and each
   829               * pointer is coro_strdup() if they wrap around?) were used for
   830               * the request buffer.  */
   831              total_read = buffer->len = new_len;
   832              memmove(buffer->value, helper->next_request, new_len);
   833              goto try_to_finalize;
   834          }
   835      }
   836
   837      for (;; n_packets++) {
   838          size_t to_read = (size_t)(buffer_size - total_read);
   839
   840          if (UNLIKELY(to_read == 0))
   841              return HTTP_TOO_LARGE;
   842
   843          n = read(request->fd, buffer->value + total_read, to_read);
   844          if (UNLIKELY(n <= 0)) {
   845              if (n < 0) {
   846                  switch (errno) {
   847                  case EAGAIN:
   848                      coro_yield(request->conn->coro, CONN_CORO_WANT_READ);
   849                      continue;
   850                  case EINTR:
   851  yield_and_read_again:
   852                      coro_yield(request->conn->coro, CONN_CORO_YIELD);
   853                      continue;
   854                  }
   855
   856                  /* Unexpected error before reading anything */
   857                  if (UNLIKELY(!total_read))
   858                      return HTTP_BAD_REQUEST;
   859              }
   860
   861              /* Client shut down orderly (n = 0), or unrecoverable error (n < 0);
   862               * shut down coro. */
   863              break;
   864          }
   865
   866          total_read += (size_t)n;
   867          buffer->len = (size_t)total_read;
   868
   869  try_to_finalize:
   870          switch (finalizer(total_read, buffer_size, request, n_packets)) {
   871          case FINALIZER_DONE:
   872              buffer->value[buffer->len] = '\0';
   873
   874  #if defined(FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION)
   875              save_to_corpus_for_fuzzing(buffer);
   876  #endif
   877
   878              return HTTP_OK;
   879
   880          case FINALIZER_TRY_AGAIN:
   881              goto yield_and_read_again;
   882
   883          case FINALIZER_ERROR_TIMEOUT:
   884              return HTTP_TIMEOUT;
   885          }
   886      }
   887
   888      coro_yield(request->conn->coro, CONN_CORO_ABORT);
   889      __builtin_unreachable();
   890      return HTTP_INTERNAL_ERROR;
   891  }
   892
   893  static enum lwan_read_finalizer
   894  read_request_finalizer(size_t total_read,
   895                         size_t buffer_size __attribute__((unused)),
   896                         struct lwan_request *request,
   897                         int n_packets)
   898  {
   899      static const size_t min_proxied_request_size =
   900          MIN_REQUEST_SIZE + sizeof(struct proxy_header_v2);
   901      struct lwan_request_parser_helper *helper = request->helper;
   902
   903      /* Yield a timeout error to avoid clients being intentionally slow and
   904       * hogging the server.  (Clients can't only connect and do nothing, they
   905       * need to send data, otherwise the DQ timer will kick in and close the
   906       * connection.  Limit the number of packets to avoid them sending just
   907       * a byte at a time.)
   908       * See calculate_n_packets() to see how this is calculated. */
   909      if (UNLIKELY(n_packets > helper->error_when_n_packets))
   910          return FINALIZER_ERROR_TIMEOUT;
   911
   912      char *crlfcrlf =
   913          memmem(helper->buffer->value, helper->buffer->len, "\r\n\r\n", 4);
   914      if (LIKELY(crlfcrlf)) {
   915          const size_t crlfcrlf_to_base =
   916              (size_t)(crlfcrlf - helper->buffer->value);
   917
   918          if (LIKELY(helper->next_request)) {
   919              helper->next_request = NULL;
   920              return FINALIZER_DONE;
   921          }
   922
   923          if (crlfcrlf_to_base >= MIN_REQUEST_SIZE - 4)
   924              return FINALIZER_DONE;
   925
   926          if (total_read > min_proxied_request_size &&
   927              request->flags & REQUEST_ALLOW_PROXY_REQS) {
   928              /* FIXME: Checking for PROXYv2 protocol header here is a layering
   929               * violation. */
   930              STRING_SWITCH_LARGE (crlfcrlf + 4) {
   931              case STR8_INT(0x00, 0x0d, 0x0a, 0x51, 0x55, 0x49, 0x54, 0x0a):
   932                  return FINALIZER_DONE;
   933              }
   934          }
   935      }
   936
   937      return FINALIZER_TRY_AGAIN;
   938  }
   939
   940  static ALWAYS_INLINE enum lwan_http_status
   941  read_request(struct lwan_request *request)
   942  {
   943      return read_from_request_socket(request, request->helper->buffer,
   944                                      DEFAULT_BUFFER_SIZE - 1 /* -1 for NUL byte */,
   945                                      read_request_finalizer);
   946  }
   947
   948  static enum lwan_read_finalizer
   949  post_data_finalizer(size_t total_read,
   950                      size_t buffer_size,
   951                      struct lwan_request *request,
   952                      int n_packets)
   953  {
   954      struct lwan_request_parser_helper *helper = request->helper;
   955
   956      if (buffer_size == total_read)
   957          return FINALIZER_DONE;
   958
   959      /* For POST requests, the body can be larger, and due to small MTUs on
   960       * most ethernet connections, responding with a timeout solely based on
   961       * number of packets doesn't work.  Use keepalive timeout instead.  */
   962      if (UNLIKELY(time(NULL) > helper->error_when_time))
   963          return FINALIZER_ERROR_TIMEOUT;
   964
   965      /* In addition to time, also estimate the number of packets based on an
   966       * usual MTU value and the request body size.  */
   967      if (UNLIKELY(n_packets > helper->error_when_n_packets))
   968          return FINALIZER_ERROR_TIMEOUT;
   969
   970      return FINALIZER_TRY_AGAIN;
   971  }
