   973  static ALWAYS_INLINE int max(int a, int b)
   974  {
   975      return (a > b) ? a : b;
   976  }
   977
   978  static ALWAYS_INLINE int calculate_n_packets(size_t total)
   979  {
   980      /* 740 = 1480 (a common MTU) / 2, so that Lwan'll optimistically error out
   981       * after ~2x number of expected packets to fully read the request body.*/
   982      return max(5, (int)(total / 740));
   983  }
