   988
   989      if (!v)
   990          return NULL;
   991
   992      if (*v != '/')
   993          return NULL;
   994
   995      if (stat(v, &st) < 0)
   996          return NULL;
   997
   998      if (!S_ISDIR(st.st_mode))
   999          return NULL;
  1000
  1001      if (!(st.st_mode & S_ISVTX)) {
  1002          lwan_status_warning(
  1003              "Using %s as temporary directory, but it doesn't have "
  1004              "the sticky bit set.",
  1005              v);
  1006      }
  1007
  1008      return v;
  1009  }
