  1046  static int create_temp_file(void)
  1047  {
  1048      char template[PATH_MAX];
  1049      mode_t prev_mask;
  1050      int ret;
  1051
  1052      if (UNLIKELY(!temp_dir))
  1053          return -ENOENT;
  1054
  1055  #if defined(O_TMPFILE)
  1056      int fd = open(temp_dir,
  1057                    O_TMPFILE | O_CREAT | O_RDWR | O_EXCL | O_CLOEXEC |
  1058                        O_NOFOLLOW | O_NOATIME,
  1059                    S_IRUSR | S_IWUSR);
  1060      if (LIKELY(fd >= 0))
  1061          return fd;
  1062  #endif
  1063
  1064      ret = snprintf(template, sizeof(template), "%s/lwanXXXXXX", temp_dir);
  1065      if (UNLIKELY(ret < 0 || ret >= (int)sizeof(template)))
  1066          return -EOVERFLOW;
  1067
  1068      prev_mask = umask_for_tmpfile(S_IRUSR | S_IWUSR);
  1069      ret = mkostemp(template, O_CLOEXEC);
  1070      umask_for_tmpfile(prev_mask);
  1071
  1072      if (LIKELY(ret >= 0))
  1073          unlink(template);
  1074
  1075      return ret;
  1076  }
