  1078  struct file_backed_buffer {
  1079      void *ptr;
  1080      size_t size;
  1081  };
  1082
  1083  static void
  1084  free_post_buffer(void *data)
  1085  {
  1086      struct file_backed_buffer *buf = data;
  1087
  1088      munmap(buf->ptr, buf->size);
  1089      free(buf);
  1090  }
  1091
  1092  static void*
  1093  alloc_post_buffer(struct coro *coro, size_t size, bool allow_file)
  1094  {
  1095      struct file_backed_buffer *buf;
  1096      void *ptr = (void *)MAP_FAILED;
  1097      int fd;
  1098
  1099      if (LIKELY(size < 1<<20)) {
  1100          ptr = coro_malloc(coro, size);
  1101
  1102          if (LIKELY(ptr))
  1103              return ptr;
  1104      }
  1105
  1106      if (UNLIKELY(!allow_file))
  1107          return NULL;
  1108
  1109      fd = create_temp_file();
  1110      if (UNLIKELY(fd < 0))
  1111          return NULL;
  1112
  1113      if (UNLIKELY(ftruncate(fd, (off_t)size) < 0)) {
  1114          close(fd);
  1115          return NULL;
  1116      }
  1117
  1118      if (MAP_HUGETLB) {
  1119          ptr = mmap(NULL, size, PROT_READ | PROT_WRITE,
  1120                     MAP_SHARED | MAP_HUGETLB, fd, 0);
  1121      }
  1122      if (UNLIKELY(ptr == MAP_FAILED))
  1123          ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
  1124      close(fd);
  1125      if (UNLIKELY(ptr == MAP_FAILED))
  1126          return NULL;
  1127
  1128      buf = coro_malloc_full(coro, sizeof(*buf), free_post_buffer);
  1129      if (UNLIKELY(!buf)) {
  1130          munmap(ptr, size);
  1131          return NULL;
  1132      }
  1133
  1134      buf->ptr = ptr;
  1135      buf->size = size;
  1136      return ptr;
  1137  }
  1138
  1139  static enum lwan_http_status read_post_data(struct lwan_request *request)
  1140  {
  1141      struct lwan_request_parser_helper *helper = request->helper;
  1142      /* Holy indirection, Batman! */
  1143      struct lwan_config *config = &request->conn->thread->lwan->config;
  1144      const size_t max_post_data_size = config->max_post_data_size;
  1145      char *new_buffer;
  1146      long parsed_size;
  1147
  1148      if (UNLIKELY(!helper->content_length.value))
  1149          return HTTP_BAD_REQUEST;
  1150      parsed_size = parse_long(helper->content_length.value, -1);
  1151      if (UNLIKELY(parsed_size < 0))
  1152          return HTTP_BAD_REQUEST;
  1153      if (UNLIKELY(parsed_size >= (long)max_post_data_size))
  1154          return HTTP_TOO_LARGE;
  1155
  1156      size_t post_data_size = (size_t)parsed_size;
  1157      size_t have;
  1158      if (!helper->next_request) {
  1159          have = 0;
  1160      } else {
  1161          char *buffer_end = helper->buffer->value + helper->buffer->len;
  1162          have = (size_t)(ptrdiff_t)(buffer_end - helper->next_request);
  1163
  1164          if (have >= post_data_size) {
  1165              helper->post_data.value = helper->next_request;
  1166              helper->post_data.len = post_data_size;
  1167              helper->next_request += post_data_size;
  1168              return HTTP_OK;
  1169          }
  1170      }
  1171
  1172      new_buffer = alloc_post_buffer(request->conn->coro, post_data_size + 1,
  1173                                     config->allow_post_temp_file);
  1174      if (UNLIKELY(!new_buffer))
  1175          return HTTP_INTERNAL_ERROR;
  1176
  1177      helper->post_data.value = new_buffer;
  1178      helper->post_data.len = post_data_size;
  1179      if (have) {
  1180          new_buffer = mempcpy(new_buffer, helper->next_request, have);
  1181          post_data_size -= have;
  1182      }
  1183      helper->next_request = NULL;
  1184
  1185      helper->error_when_time = time(NULL) + config->keep_alive_timeout;
  1186      helper->error_when_n_packets = calculate_n_packets(post_data_size);
  1187
  1188      struct lwan_value buffer = {.value = new_buffer,
  1189                                  .len = post_data_size};
  1190      return read_from_request_socket(request, &buffer, buffer.len,
  1191                                      post_data_finalizer);
  1192  }
  1193
  1194  static char *
  1195  parse_proxy_protocol(struct lwan_request *request, char *buffer)
  1196  {
  1197      STRING_SWITCH(buffer) {
  1198      case STR4_INT('P','R','O','X'):
  1199          return parse_proxy_protocol_v1(request, buffer);
  1200      case STR4_INT('\x0D','\x0A','\x0D','\x0A'):
  1201          return parse_proxy_protocol_v2(request, buffer);
  1202      }
  1203
  1204      return buffer;
  1205  }
  1206
  1207  static enum lwan_http_status parse_http_request(struct lwan_request *request)
  1208  {
  1209      struct lwan_request_parser_helper *helper = request->helper;
  1210      char *buffer = helper->buffer->value;
  1211
  1212      if (request->flags & REQUEST_ALLOW_PROXY_REQS) {
  1213          /* REQUEST_ALLOW_PROXY_REQS will be cleared in lwan_process_request() */
  1214
  1215          buffer = parse_proxy_protocol(request, buffer);
  1216          if (UNLIKELY(!buffer))
  1217              return HTTP_BAD_REQUEST;
  1218      }
  1219
  1220      buffer = ignore_leading_whitespace(buffer);
  1221
  1222      if (UNLIKELY(buffer > helper->buffer->value + helper->buffer->len -
  1223                                 MIN_REQUEST_SIZE))
  1224          return HTTP_BAD_REQUEST;
  1225
  1226      char *path = identify_http_method(request, buffer);
  1227      if (UNLIKELY(!path))
  1228          return HTTP_NOT_ALLOWED;
  1229
  1230      buffer = identify_http_path(request, path);
  1231      if (UNLIKELY(!buffer))
  1232          return HTTP_BAD_REQUEST;
  1233
  1234      if (UNLIKELY(!parse_headers(helper, buffer)))
  1235          return HTTP_BAD_REQUEST;
  1236
  1237      ssize_t decoded_len = url_decode(request->url.value);
  1238      if (UNLIKELY(decoded_len < 0))
  1239          return HTTP_BAD_REQUEST;
  1240      request->original_url.len = request->url.len = (size_t)decoded_len;
  1241
  1242      parse_connection_header(request);
  1243
  1244      return HTTP_OK;
  1245  }
  1246
  1247  static enum lwan_http_status
  1248  prepare_websocket_handshake(struct lwan_request *request, char **encoded)
  1249  {
  1250      static const unsigned char websocket_uuid[] =
  1251          "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";
  1252      unsigned char digest[20];
  1253      sha1_context ctx;
  1254
  1255      if (UNLIKELY(request->flags & RESPONSE_SENT_HEADERS))
  1256          return HTTP_INTERNAL_ERROR;
  1257
  1258      if (UNLIKELY(!(request->conn->flags & CONN_IS_UPGRADE)))
  1259          return HTTP_BAD_REQUEST;
  1260
  1261      const char *upgrade = lwan_request_get_header(request, "Upgrade");
  1262      if (UNLIKELY(!upgrade || !streq(upgrade, "websocket")))
  1263          return HTTP_BAD_REQUEST;
  1264
  1265      const char *sec_websocket_key =
  1266          lwan_request_get_header(request, "Sec-WebSocket-Key");
  1267      if (UNLIKELY(!sec_websocket_key))
  1268          return HTTP_BAD_REQUEST;
  1269      const size_t sec_websocket_key_len = strlen(sec_websocket_key);
  1270      if (UNLIKELY(!base64_validate((void *)sec_websocket_key, sec_websocket_key_len)))
  1271          return HTTP_BAD_REQUEST;
  1272
  1273      sha1_init(&ctx);
  1274      sha1_update(&ctx, (void *)sec_websocket_key, sec_websocket_key_len);
  1275      sha1_update(&ctx, websocket_uuid, sizeof(websocket_uuid) - 1);
  1276      sha1_finalize(&ctx, digest);
  1277
  1278      *encoded = (char *)base64_encode(digest, sizeof(digest), NULL);
  1279      if (UNLIKELY(!*encoded))
  1280          return HTTP_INTERNAL_ERROR;
  1281      coro_defer(request->conn->coro, free, *encoded);
  1282
  1283      return HTTP_SWITCHING_PROTOCOLS;
  1284  }
  1285
  1286  enum lwan_http_status
  1287  lwan_request_websocket_upgrade(struct lwan_request *request)
  1288  {
  1289      char header_buf[DEFAULT_HEADERS_SIZE];
  1290      size_t header_buf_len;
  1291      char *encoded;
  1292
  1293      enum lwan_http_status r = prepare_websocket_handshake(request, &encoded);
  1294      if (r != HTTP_SWITCHING_PROTOCOLS)
  1295          return r;
  1296
  1297      request->flags |= RESPONSE_NO_CONTENT_LENGTH;
  1298      header_buf_len = lwan_prepare_response_header_full(
  1299          request, HTTP_SWITCHING_PROTOCOLS, header_buf, sizeof(header_buf),
  1300          (struct lwan_key_value[]){
  1301              /* Connection: Upgrade is implicit if conn->flags & CONN_IS_UPGRADE */
  1302              {.key = "Sec-WebSocket-Accept", .value = encoded},
  1303              {.key = "Upgrade", .value = "websocket"},
  1304              {},
  1305          });
  1306      if (UNLIKELY(!header_buf_len))
  1307          return HTTP_INTERNAL_ERROR;
  1308
  1309      request->conn->flags |= CONN_IS_WEBSOCKET;
  1310      lwan_send(request, header_buf, header_buf_len, 0);
  1311      coro_yield(request->conn->coro, CONN_CORO_WANT_READ_WRITE);
  1312
  1313      return HTTP_SWITCHING_PROTOCOLS;
  1314  }
  1315
  1316  static enum lwan_http_status prepare_for_response(struct lwan_url_map *url_map,
  1317                                                    struct lwan_request *request)
  1318  {
  1319      request->url.value += url_map->prefix_len;
  1320      request->url.len -= url_map->prefix_len;
  1321
  1322      if (url_map->flags & HANDLER_MUST_AUTHORIZE) {
  1323          const char *authorization =
  1324              lwan_request_get_header(request, "Authorization");
  1325          struct lwan_value header = {
  1326              .value = (char*)authorization,
  1327              .len = authorization ? strlen(authorization) : 0,
  1328          };
  1329
  1330          if (!lwan_http_authorize(request, &header,
  1331                                   url_map->authorization.realm,
  1332                                   url_map->authorization.password_file))
  1333              return HTTP_NOT_AUTHORIZED;
  1334      }
  1335
  1336      while (*request->url.value == '/' && request->url.len > 0) {
  1337          request->url.value++;
  1338          request->url.len--;
  1339      }
  1340
  1341      if (url_map->flags & HANDLER_PARSE_ACCEPT_ENCODING)
  1342          parse_accept_encoding(request);
  1343
  1344      if (lwan_request_get_method(request) == REQUEST_METHOD_POST) {
  1345          enum lwan_http_status status;
  1346
  1347          if (!(url_map->flags & HANDLER_HAS_POST_DATA)) {
  1348              /* FIXME: Discard POST data here? If a POST request is sent
  1349               * to a handler that is not supposed to handle a POST request,
  1350               * the next request in the pipeline will fail because the
  1351               * body of the previous request will be used as the next
  1352               * request itself. */
  1353              return HTTP_NOT_ALLOWED;
  1354          }
  1355
  1356          status = read_post_data(request);
  1357          if (UNLIKELY(status != HTTP_OK))
  1358              return status;
  1359      }
  1360
  1361      return HTTP_OK;
  1362  }
  1363
  1364  static bool handle_rewrite(struct lwan_request *request)
  1365  {
  1366      struct lwan_request_parser_helper *helper = request->helper;
  1367
  1368      request->flags &= ~RESPONSE_URL_REWRITTEN;
  1369
  1370      parse_fragment_and_query(request, request->url.value + request->url.len);
  1371
  1372      helper->urls_rewritten++;
  1373      if (UNLIKELY(helper->urls_rewritten > 4)) {
  1374          lwan_default_response(request, HTTP_INTERNAL_ERROR);
  1375          return false;
  1376      }
  1377
  1378      return true;
  1379  }
  1380
  1381  char *lwan_process_request(struct lwan *l,
  1382                             struct lwan_request *request,
  1383                             struct lwan_value *buffer,
  1384                             char *next_request)
  1385  {
  1386      char *header_start[N_HEADER_START];
  1387      struct lwan_request_parser_helper helper = {
  1388          .buffer = buffer,
  1389          .next_request = next_request,
  1390          .error_when_n_packets = calculate_n_packets(DEFAULT_BUFFER_SIZE),
  1391          .header_start = header_start,
  1392      };
  1393      enum lwan_http_status status;
  1394      struct lwan_url_map *url_map;
  1395
  1396      request->helper = &helper;
  1397
  1398      status = read_request(request);
  1399      if (UNLIKELY(status != HTTP_OK)) {
  1400          /* This request was bad, but maybe there's a good one in the
  1401           * pipeline.  */
  1402          if (status == HTTP_BAD_REQUEST && helper.next_request)
  1403              goto out;
  1404
  1405          /* Response here can be: HTTP_TOO_LARGE, HTTP_BAD_REQUEST (without
  1406           * next request), or HTTP_TIMEOUT.  Nothing to do, just abort the
  1407           * coroutine.  */
  1408          lwan_default_response(request, status);
  1409          coro_yield(request->conn->coro, CONN_CORO_ABORT);
  1410          __builtin_unreachable();
  1411      }
  1412
  1413      status = parse_http_request(request);
  1414      if (UNLIKELY(status != HTTP_OK)) {
  1415          lwan_default_response(request, status);
  1416          goto out;
  1417      }
  1418
  1419  lookup_again:
  1420      url_map = lwan_trie_lookup_prefix(&l->url_map_trie, request->url.value);
  1421      if (UNLIKELY(!url_map)) {
  1422          lwan_default_response(request, HTTP_NOT_FOUND);
  1423          goto out;
  1424      }
  1425
  1426      status = prepare_for_response(url_map, request);
  1427      if (UNLIKELY(status != HTTP_OK)) {
  1428          lwan_default_response(request, status);
  1429          goto out;
  1430      }
  1431
  1432      status = url_map->handler(request, &request->response, url_map->data);
  1433      if (UNLIKELY(url_map->flags & HANDLER_CAN_REWRITE_URL)) {
  1434          if (request->flags & RESPONSE_URL_REWRITTEN) {
  1435              if (LIKELY(handle_rewrite(request)))
  1436                  goto lookup_again;
  1437              goto out;
  1438          }
  1439      }
  1440
  1441      lwan_response(request, status);
  1442
  1443  out:
  1444      return helper.next_request;
  1445  }
