  1547  static void remove_sleep(void *data1, void *data2)
  1548  {
  1549      struct timeouts *wheel = data1;
  1550      struct timeout *timeout = data2;
  1551      struct lwan_request *request =
  1552          container_of(timeout, struct lwan_request, timeout);
  1553
  1554      if (request->conn->flags & CONN_SUSPENDED_TIMER)
  1555          timeouts_del(wheel, timeout);
  1556
  1557      request->conn->flags &= ~CONN_HAS_REMOVE_SLEEP_DEFER;
  1558  }
  1559
  1560  void lwan_request_sleep(struct lwan_request *request, uint64_t ms)
  1561  {
  1562      struct lwan_connection *conn = request->conn;
  1563      struct timeouts *wheel = conn->thread->wheel;
  1564
  1565      request->timeout = (struct timeout) {};
  1566      timeouts_add(wheel, &request->timeout, ms);
  1567
  1568      if (!(conn->flags & CONN_HAS_REMOVE_SLEEP_DEFER)) {
  1569          coro_defer2(conn->coro, remove_sleep, wheel, &request->timeout);
  1570          conn->flags |= CONN_HAS_REMOVE_SLEEP_DEFER;
  1571      }
  1572
  1573      coro_yield(conn->coro, CONN_CORO_SUSPEND_TIMER);
  1574  }
