   261  size_t lwan_prepare_response_header_full(
   262      struct lwan_request *request,
   263      enum lwan_http_status status,
   264      char headers[],
   265      size_t headers_buf_size,
   266      const struct lwan_key_value *additional_headers)
   267  {
   268      char *p_headers;
   269      char *p_headers_end = headers + headers_buf_size;
   270      char buffer[INT_TO_STR_BUFFER_SIZE];
   271      bool date_overridden = false;
   272      bool expires_overridden = false;
   273
   274      p_headers = headers;
   275
   276      if (request->flags & REQUEST_IS_HTTP_1_0)
   277          APPEND_CONSTANT("HTTP/1.0 ");
   278      else
   279          APPEND_CONSTANT("HTTP/1.1 ");
   280      APPEND_STRING(lwan_http_status_as_string_with_code(status));
   281
   282      if (request->flags & RESPONSE_CHUNKED_ENCODING) {
   283          APPEND_CONSTANT("\r\nTransfer-Encoding: chunked");
   284      } else if (request->flags & RESPONSE_NO_CONTENT_LENGTH) {
   285          /* Do nothing. */
   286      } else if (!(request->flags & RESPONSE_STREAM)) {
   287          APPEND_CONSTANT("\r\nContent-Length: ");
   288          APPEND_UINT(lwan_strbuf_get_length(request->response.buffer));
   289      }
   290
   291      if ((status < HTTP_BAD_REQUEST && additional_headers)) {
   292          const struct lwan_key_value *header;
   293
   294          for (header = additional_headers; header->key; header++) {
   295              STRING_SWITCH_L(header->key) {
   296              case STR4_INT_L('S', 'e', 'r', 'v'):
   297                  if (LIKELY(streq(header->key + 4, "er")))
   298                      continue;
   299                  break;
   300              case STR4_INT_L('D', 'a', 't', 'e'):
   301                  if (LIKELY(*(header->key + 4) == '\0'))
   302                      date_overridden = true;
   303                  break;
   304              case STR4_INT_L('E', 'x', 'p', 'i'):
   305                  if (LIKELY(streq(header->key + 4, "res")))
   306                      expires_overridden = true;
   307                  break;
   308              }
   309
   310              RETURN_0_ON_OVERFLOW(4);
   311              APPEND_CHAR_NOCHECK('\r');
   312              APPEND_CHAR_NOCHECK('\n');
   313              APPEND_STRING(header->key);
   314              APPEND_CHAR_NOCHECK(':');
   315              APPEND_CHAR_NOCHECK(' ');
   316              APPEND_STRING(header->value);
   317          }
   318      } else if (status == HTTP_NOT_AUTHORIZED) {
   319          const struct lwan_key_value *header;
   320
   321          for (header = additional_headers; header->key; header++) {
   322              if (streq(header->key, "WWW-Authenticate")) {
   323                  APPEND_CONSTANT("\r\nWWW-Authenticate: ");
   324                  APPEND_STRING(header->value);
   325                  break;
   326              }
   327          }
   328      }
   329
   330      if (request->conn->flags & CONN_IS_UPGRADE) {
   331          APPEND_CONSTANT("\r\nConnection: Upgrade");
   332      } else {
   333          if (request->conn->flags & CONN_IS_KEEP_ALIVE) {
   334              APPEND_CONSTANT("\r\nConnection: keep-alive");
   335          } else {
   336              APPEND_CONSTANT("\r\nConnection: close");
   337          }
   338
   339          if (LIKELY(request->response.mime_type)) {
   340              APPEND_CONSTANT("\r\nContent-Type: ");
   341              APPEND_STRING(request->response.mime_type);
   342          }
   343      }
   344
   345      if (LIKELY(!date_overridden)) {
   346          APPEND_CONSTANT("\r\nDate: ");
   347          APPEND_STRING_LEN(request->conn->thread->date.date, 29);
   348      }
   349
   350      if (LIKELY(!expires_overridden)) {
   351          APPEND_CONSTANT("\r\nExpires: ");
   352          APPEND_STRING_LEN(request->conn->thread->date.expires, 29);
   353      }
   354
   355      if (request->flags & REQUEST_ALLOW_CORS) {
   356          APPEND_CONSTANT(
   357              "\r\nAccess-Control-Allow-Origin: *"
   358              "\r\nAccess-Control-Allow-Methods: GET, POST, OPTIONS"
   359              "\r\nAccess-Control-Allow-Credentials: true"
   360              "\r\nAccess-Control-Allow-Headers: Origin, Accept, Content-Type");
   361      }
   362
   363      APPEND_CONSTANT("\r\nServer: lwan\r\n\r\n\0");
   364
   365      return (size_t)(p_headers - headers - 1);
   366  }
