   369  #undef APPEND_CHAR_NOCHECK
   370  #undef APPEND_CONSTANT
   371  #undef APPEND_STRING
   372  #undef APPEND_STRING_LEN
   373  #undef APPEND_UINT
   374  #undef RETURN_0_ON_OVERFLOW
