   391      if (request->flags & RESPONSE_SENT_HEADERS)
   392          return false;
   393
   394      request->flags |= RESPONSE_CHUNKED_ENCODING;
   395      buffer_len = lwan_prepare_response_header(request, status, buffer,
   396                                                DEFAULT_BUFFER_SIZE);
