   406  void lwan_response_send_chunk(struct lwan_request *request)
   407  {
   408      if (!(request->flags & RESPONSE_SENT_HEADERS)) {
   409          if (UNLIKELY(!lwan_response_set_chunked(request, HTTP_OK)))
   410              return;
   411      }
   412
   413      size_t buffer_len = lwan_strbuf_get_length(request->response.buffer);
   414      if (UNLIKELY(!buffer_len)) {
   415          static const char last_chunk[] = "0\r\n\r\n";
   416          lwan_send(request, last_chunk, sizeof(last_chunk) - 1, 0);
   417          return;
   418      }
   419
   420      char chunk_size[3 * sizeof(size_t) + 2];
   421      int converted_len =
   422          snprintf(chunk_size, sizeof(chunk_size), "%zx\r\n", buffer_len);
   423      if (UNLIKELY(converted_len < 0 ||
   424                   (size_t)converted_len >= sizeof(chunk_size))) {
   425          coro_yield(request->conn->coro, CONN_CORO_ABORT);
   426          __builtin_unreachable();
   427      }
   428      size_t chunk_size_len = (size_t)converted_len;
   429
   430      struct iovec chunk_vec[] = {
   431          {.iov_base = chunk_size, .iov_len = chunk_size_len},
   432          {.iov_base = lwan_strbuf_get_buffer(request->response.buffer),
   433           .iov_len = buffer_len},
   434          {.iov_base = "\r\n", .iov_len = 2},
   435      };
   436
   437      lwan_writev(request, chunk_vec, N_ELEMENTS(chunk_vec));
   438
   439      lwan_strbuf_reset(request->response.buffer);
   440      coro_yield(request->conn->coro, CONN_CORO_WANT_WRITE);
   441  }
