  1447  static inline void *
  1448  value_lookup(const struct lwan_key_value_array *array, const char *key)
  1449  {
  1450      const struct lwan_array *la = (const struct lwan_array *)array;
  1451
  1452      if (LIKELY(la->elements)) {
  1453          struct lwan_key_value k = { .key = (char *)key };
  1454          struct lwan_key_value *entry;
  1455
  1456          entry = bsearch(&k, la->base, la->elements, sizeof(k), key_value_compare);
  1457          if (LIKELY(entry))
  1458              return entry->value;
  1459      }
  1460
  1461      return NULL;
  1462  }
