  1514  const char *
  1515  lwan_request_get_remote_address(struct lwan_request *request,
  1516              char buffer[static INET6_ADDRSTRLEN])
  1517  {
  1518      struct sockaddr_storage non_proxied_addr = { .ss_family = AF_UNSPEC };
  1519      struct sockaddr_storage *sock_addr;
  1520
  1521      if (request->flags & REQUEST_PROXIED) {
  1522          sock_addr = (struct sockaddr_storage *)&request->proxy->from;
  1523
  1524          if (UNLIKELY(sock_addr->ss_family == AF_UNSPEC))
  1525              return memcpy(buffer, "*unspecified*", sizeof("*unspecified*"));
  1526      } else {
  1527          socklen_t sock_len = sizeof(non_proxied_addr);
  1528
  1529          sock_addr = &non_proxied_addr;
  1530
  1531          if (UNLIKELY(getpeername(request->fd,
  1532                                   (struct sockaddr *) sock_addr,
  1533                                   &sock_len) < 0))
  1534              return NULL;
  1535      }
  1536
  1537      if (sock_addr->ss_family == AF_INET)
  1538          return inet_ntop(AF_INET,
  1539                           &((struct sockaddr_in *) sock_addr)->sin_addr,
  1540                           buffer, INET6_ADDRSTRLEN);
  1541
  1542      return inet_ntop(AF_INET6,
  1543                       &((struct sockaddr_in6 *) sock_addr)->sin6_addr,
  1544                       buffer, INET6_ADDRSTRLEN);
  1545  }
