  1675  __attribute__((used)) int fuzz_parse_http_request(const uint8_t *data,
  1676                                                    size_t length)
  1677  {
  1678      static struct coro_switcher switcher;
  1679      static struct coro *coro;
  1680      static char *header_start[N_HEADER_START];
  1681      static char data_copy[32767] = {0};
  1682
  1683      if (length > sizeof(data_copy))
  1684          length = sizeof(data_copy);
  1685      memcpy(data_copy, data, length);
  1686
  1687      if (!coro)
  1688          coro = coro_new(&switcher, useless_coro_for_fuzzing, NULL);
  1689
  1690      struct lwan_request_parser_helper helper = {
  1691          .buffer = &(struct lwan_value){.value = data_copy, .len = length},
  1692          .header_start = header_start,
  1693          .error_when_n_packets = 2,
  1694      };
  1695      struct lwan_connection conn = {.coro = coro};
  1696      struct lwan_proxy proxy = {};
  1697      struct lwan_request request = {
  1698          .helper = &helper,
  1699          .conn = &conn,
  1700          .flags = REQUEST_ALLOW_PROXY_REQS,
  1701          .proxy = &proxy,
  1702      };
  1703
  1704      /* If the finalizer isn't happy with a request, there's no point in
  1705       * going any further with parsing it. */
  1706      if (read_request_finalizer(length, sizeof(data_copy), &request, 1) !=
  1707          FINALIZER_DONE)
  1708          return 0;
  1709
  1710      /* read_from_request_socket() NUL-terminates the string */
  1711      data_copy[length - 1] = '\0';
  1712
  1713      if (parse_http_request(&request) == HTTP_OK) {
  1714          off_t trash1;
  1715          time_t trash2;
  1716          size_t gen = coro_deferred_get_generation(coro);
  1717
  1718          /* Only pointers were set in helper struct; actually parse them here. */
  1719          parse_accept_encoding(&request);
  1720
  1721          /* Requesting these items will force them to be parsed, and also exercise
  1722           * the lookup function. */
  1723
  1724  #define NO_DISCARD(...)                                                        \
  1725      do {                                                                       \
  1726          typeof(__VA_ARGS__) no_discard_ = __VA_ARGS__;                         \
  1727          __asm__ __volatile__("" ::"g"(no_discard_) : "memory");                \
  1728      } while (0)
  1729
  1730          NO_DISCARD(lwan_request_get_header(&request, "Non-Existing-Header"));
  1731          NO_DISCARD(lwan_request_get_header(&request, "Host")); /* Usually existing short header */
  1732          NO_DISCARD(lwan_request_get_cookie(&request, "Non-Existing-Cookie"));
  1733          NO_DISCARD(lwan_request_get_cookie(&request, "FOO")); /* Set by some tests */
  1734          NO_DISCARD(lwan_request_get_query_param(&request, "Non-Existing-Query-Param"));
  1735          NO_DISCARD(lwan_request_get_post_param(&request, "Non-Existing-Post-Param"));
  1736          NO_DISCARD(fuzz_websocket_handshake(&request));
  1737
  1738          lwan_request_get_range(&request, &trash1, &trash1);
  1739          NO_DISCARD(trash1);
  1740
  1741          lwan_request_get_if_modified_since(&request, &trash2);
  1742          NO_DISCARD(trash2);
  1743
  1744  #undef NO_DISCARD
  1745
  1746          coro_deferred_run(coro, gen);
  1747      }
  1748
  1749      return 0;
  1750  }
