    77  static ALWAYS_INLINE size_t lwan_nextpow2(size_t number)
    78  {
    79  #if defined(HAVE_BUILTIN_CLZLL)
    80      static const int size_bits = (int)sizeof(number) * CHAR_BIT;
    81
    82      if (sizeof(size_t) == sizeof(unsigned int)) {
    83          return (size_t)1 << (size_bits - __builtin_clz((unsigned int)number));
    84      } else if (sizeof(size_t) == sizeof(unsigned long)) {
    85          return (size_t)1 << (size_bits - __builtin_clzl((unsigned long)number));
    86      } else if (sizeof(size_t) == sizeof(unsigned long long)) {
    87          return (size_t)1 << (size_bits - __builtin_clzll((unsigned long long)number));
    88      } else {
    89          (void)size_bits;
    90      }
    91  #endif
    92
    93      number--;
    94      number |= number >> 1;
    95      number |= number >> 2;
    96      number |= number >> 4;
    97      number |= number >> 8;
    98      number |= number >> 16;
    99
   100      return number + 1;
   101  }
