   125  lwan_aligned_alloc(size_t n, size_t alignment)
   126  {
   127      void *ret;
   128
   129      assert((alignment & (alignment - 1)) == 0);
   130
   131      n = (n + alignment - 1) & ~(alignment - 1);
   132      if (UNLIKELY(posix_memalign(&ret, alignment, n)))
   133          return NULL;
   134
   135      return ret;
